			let sin_tk: f32 = sin(tk);
			let cos_tk: f32 = cos(tk);
			let g_theta: f32 = uniform.fisheye_k * sin_tk / cos_tk;
			let fisheye_s: f32 = select(select(0.0, 1.0 / neg_z, neg_z > 0.0), g_theta / r_xy, r_xy > 1e-4);
